<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>杀戮尖塔复刻 - 地图界面</title>
    <style>
        :root {
            --bg-color: #0d0e12;
            --parchment-base: #c8bca3;
            --parchment-dark: #a89f85;
            --text-gold: #f2c94c;
            --text-blue: #90cdf4;
            --hud-bg: rgba(20, 25, 30, 0.9);
            --border-color: #4a5568;
            --accent-red: #e53e3e;
        }

        * {
            box-sizing: border-box;
            user-select: none;
            -webkit-user-drag: none;
        }

        body {
            margin: 0;
            padding: 0;
            background-color: var(--bg-color);
            font-family: "Segoe UI", "Microsoft YaHei", sans-serif;
            height: 100vh;
            width: 100vw;
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
            color: white;
        }

        /* 游戏容器 */
        #game-container {
            position: relative;
            width: 1200px;
            height: 675px; /* 16:9 比例 */
            background-color: #000;
            box-shadow: 0 0 50px rgba(0,0,0,0.5);
        }

        /* --- 顶部 HUD --- */
        #top-hud {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 60px;
            padding: 10px 20px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            z-index: 100;
            /* 背景透明，依靠图标自身背景或文字阴影 */
        }

        .hud-left, .hud-center, .hud-right {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .char-info {
            font-size: 18px;
            font-weight: bold;
            text-shadow: 2px 2px 0 #000;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .char-sub {
            font-size: 14px;
            color: #a0aec0;
            font-weight: normal;
        }

        .stat-item {
            display: flex;
            align-items: center;
            background: #222;
            padding: 4px 10px;
            border-radius: 4px;
            border: 1px solid #444;
            font-family: monospace;
            font-size: 16px;
            font-weight: bold;
        }

        .icon-heart { color: var(--accent-red); margin-right: 5px; }
        .icon-gold { color: var(--text-gold); margin-right: 5px; }

        .potion-slots {
            display: flex;
            gap: 5px;
            background: rgba(255,255,255,0.1);
            padding: 5px;
            border-radius: 20px;
            border: 2px solid #fff;
        }
        .potion-slot {
            width: 30px;
            height: 30px;
            background: #333;
            border-radius: 50%;
            border: 1px solid #666;
        }

        .hud-btn {
            width: 40px;
            height: 40px;
            background: #444;
            border-radius: 4px;
            display: flex;
            justify-content: center;
            align-items: center;
            cursor: pointer;
            border: 1px solid #666;
        }
        .hud-btn:hover { background: #555; }
        .btn-settings { background: #718096; }
        .btn-map { background: #d69e2e; } /* Map icon bg */
        .btn-discard { background: #9b2c2c; }

        /* --- 右侧菜单 --- */
        #right-menu {
            position: absolute;
            top: 50%;
            right: 20px;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .menu-btn {
            width: 44px;
            height: 44px;
            background: rgba(80, 70, 60, 0.95);
            border: 2px solid #5a4a3a;
            border-radius: 6px;
            display: flex;
            justify-content: center;
            align-items: center;
            cursor: pointer;
            transition: all 0.2s;
            position: relative;
        }
        .menu-btn:hover {
            transform: translateX(-5px);
            background: rgba(100, 90, 80, 0.95);
        }
        .menu-btn.active {
            border-color: var(--text-gold);
            background: rgba(120, 110, 100, 0.95);
        }

        /* Tooltip for menu */
        .menu-btn::after {
            content: attr(data-label);
            position: absolute;
            right: 50px;
            background: #222;
            color: #ddd;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 12px;
            white-space: nowrap;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.2s;
            border: 1px solid #555;
        }
        .menu-btn:hover::after { opacity: 1; }

        /* --- 羊皮纸地图区域 --- */
        #map-wrapper {
            position: absolute;
            top: 60px; /* Below HUD */
            bottom: 0;
            left: 0;
            right: 180px; /* Space for menu */
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* 羊皮纸本体 */
        #parchment {
            width: 90%;
            height: 95%;
            background-color: var(--parchment-base);
            /* 模拟纸张纹理和污渍 - 使用CSS噪点或渐变模拟 */
            background-image: 
                radial-gradient(circle at 20% 30%, rgba(160, 140, 110, 0.4) 0%, transparent 20%),
                radial-gradient(circle at 80% 70%, rgba(160, 140, 110, 0.3) 0%, transparent 25%),
                linear-gradient(135deg, transparent 40%, rgba(255,255,255,0.1) 50%, transparent 60%);

            position: relative;
            box-shadow: 
                inset 0 0 100px rgba(0,0,0,0.2), /* 内部阴影增加陈旧感 */
                0 10px 30px rgba(0,0,0,0.5);

            /* SVG 滤镜用于边缘效果 */
            filter: url(#roughEdges);
            clip-path: polygon(
                0% 2%, 2% 0%, 98% 1%, 100% 3%, 
                99% 98%, 97% 100%, 3% 99%, 1% 97%
            ); /* 基础不规则形状 */
        }

        /* 顶部卷边装饰 (伪元素) */
        #parchment::before {
            content: '';
            position: absolute;
            top: -15px;
            left: 5%;
            right: 5%;
            height: 30px;
            background: linear-gradient(to bottom, #dcd4c0, var(--parchment-base));
            border-radius: 50% / 10%; /* 圆柱体卷曲感 */
            z-index: 2;
            box-shadow: 0 2px 5px rgba(0,0,0,0.2);
            border-top: 2px solid #bfaea0;
            border-bottom: 1px solid #a89f85;
        }

        /* 底部撕裂边 (SVG Mask 实现) */
        .tear-edge-bottom {
            position: absolute;
            bottom: -10px;
            left: 0;
            width: 100%;
            height: 20px;
            background: #888; /* Fallback */
            z-index: 2;
        }

        /* --- 地图内容层 --- */
        #map-content {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 5;
            pointer-events: auto; /* 允许点击节点 */
        }

        svg#map-svg {
            width: 100%;
            height: 100%;
            overflow: visible;
        }

        /* 路径样式 */
        .map-path {
            fill: none;
            stroke: #8b7355;
            stroke-width: 4;
            stroke-linecap: round;
            stroke-dasharray: 8, 8; /* 虚线效果 */
        }
        .map-path.available {
            stroke: #d4a373;
            stroke-width: 5;
        }
        .map-path.taken {
            stroke: #5c4033; /* 深色已走路径 */
            stroke-width: 6;
            stroke-dasharray: none;
        }

        /* 节点样式 */
        .node-circle {
            fill: #5c4a3a;
            stroke: #3e3226;
            stroke-width: 3px;
            cursor: pointer;
            transition: all 0.3s ease;
        }
        .node-circle:hover {
            transform: scale(1.2);
            transform-origin: center;
            filter: drop-shadow(0 0 5px rgba(255,255,255,0.5));
        }

        /* 节点类型颜色 */
        .node-enemy { fill: #a33b3b; stroke: #5a1a1a; }
        .node-elite { fill: #b7791f; stroke: #744210; }
        .node-boss { fill: #c53030; stroke: #4a1515; stroke-width: 4px; }
        .node-treasure { fill: #2f855a; stroke: #1a4731; }
        .node-rest { fill: #3182ce; stroke: #2a4365; }
        .node-event { fill: #805ad5; stroke: #44337a; }
        .node-shop { fill: #dd6b20; stroke: #7b341e; }

        .node-icon {
            pointer-events: none;
            fill: #fff;
            font-family: sans-serif;
            font-weight: bold;
            text-anchor: middle;
            dominant-baseline: central;
            font-size: 16px;
        }

        /* --- 弹窗/遮罩层 --- */
        #overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.4);
            backdrop-filter: blur(2px);
            z-index: 200;
            display: flex;
            justify-content: center;
            align-items: center;
            opacity: 0;
            animation: fadeIn 1s forwards;
        }

        @keyframes fadeIn {
            to { opacity: 1; }
        }

        .act-banner {
            text-align: center;
            transform: translateY(-20px);
        }

        .act-title-small {
            color: var(--text-blue);
            font-size: 24px;
            letter-spacing: 2px;
            margin-bottom: 10px;
            text-transform: uppercase;
            text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        }

        .act-title-main {
            color: var(--text-gold);
            font-size: 48px;
            font-family: 'Times New Roman', serif;
            letter-spacing: 1px;
            text-shadow: 0 4px 10px rgba(0,0,0,0.6);
            font-style: italic;
        }

        /* 隐藏的SVG滤镜定义 */
        .svg-filters {
            position: absolute;
            width: 0;
            height: 0;
        }

    </style>
</head>
<body>

    <!-- 定义滤镜 -->
    <svg class="svg-filters">
        <defs>
            <filter id="roughEdges">
                <!-- 简单的置换贴图模拟粗糙边缘 -->
                <feTurbulence type="fractalNoise" baseFrequency="0.04" numOctaves="3" result="noise" />
                <feDisplacementMap in="SourceGraphic" in2="noise" scale="5" xChannelSelector="R" yChannelSelector="G" />
            </filter>

            <!-- 撕裂边缘路径 -->
            <clipPath id="tearClip">
                <path d="M0,650 L50,645 L100,655 L150,640 L200,658 L250,642 L300,660 L350,645 L400,655 L450,638 L500,652 L550,642 L600,658 L650,645 L700,655 L750,640 L800,660 L850,645 L900,655 L950,640 L1000,660 L1050,645 L1100,655 L1150,640 L1200,650 L1200,700 L0,700 Z" />
            </clipPath>
        </defs>
    </svg>

    <div id="game-container">

        <!-- 顶部 HUD -->
        <header id="top-hud">
            <div class="hud-left">
                <div class="char-info">
                    铁甲战士 <span class="char-sub">Ironclad</span>
                </div>
                <div class="stat-item">
                    <span class="icon-heart">❤</span> 75/75
                </div>
                <div class="stat-item">
                    <span class="icon-gold">💰</span> 99
                </div>
            </div>

            <div class="hud-center">
                <div class="potion-slots">
                    <div class="potion-slot"></div>
                    <div class="potion-slot"></div>
                    <div class="potion-slot"></div>
                </div>
            </div>

            <div class="hud-right">
                <div class="stat-item" style="background:none; border:none;">
                    📦 0
                </div>
                <div class="hud-btn btn-map" title="地图">🗺️</div>
                <div class="hud-btn btn-settings" title="设置">⚙️</div>
                <div class="hud-btn btn-discard" title="牌组">📜</div>
                <div class="hud-btn" style="background:#742a2a;" title="设置">⋮</div>
                <div class="hud-btn" style="background:#742a2a;" title="设置">⏸</div>
            </div>
        </header>

        <!-- 右侧菜单 -->
        <aside id="right-menu">
            <div class="menu-btn active" data-label="图 例">📋</div>
            <div class="menu-btn" data-label="地 图">📍</div>
            <div class="menu-btn" data-label="回 合">🔄</div>
            <div class="menu-btn" data-label="商 店">🛒</div>
            <div class="menu-btn" data-label="篇 章">📖</div>
            <div class="menu-btn" data-label="离 火">🔥</div>
            <div class="menu-btn" data-label="敌 人">⚔️</div>
            <div class="menu-btn" data-label="精 英">💀</div>
        </aside>

        <!-- 地图主体 -->
        <main id="map-wrapper">
            <div id="parchment">
                <!-- 底部撕裂边 -->
                <svg class="tear-edge-bottom" viewBox="0 0 1200 50" preserveAspectRatio="none" style="height: 30px; width: 100%;">
                     <path d="M0,10 Q30,25 60,10 T120,10 T180,15 T240,5 T300,20 T360,10 T420,15 T480,5 T540,20 T600,10 T660,15 T720,5 T780,20 T840,10 T900,15 T960,5 T1020,20 T1080,10 T1140,15 T1200,10 V50 H0 Z" fill="#c8bca3" stroke="#a89f85" stroke-width="2"/>
                </svg>

                <div id="map-content">
                    <svg id="map-svg" viewBox="0 0 800 600" preserveAspectRatio="xMidYMid meet">
                        <!-- 动态生成的地图内容将放在这里 -->
                        <g id="paths-layer"></g>
                        <g id="nodes-layer"></g>
                    </svg>
                </div>
            </div>
        </main>

        <!-- 幕间过渡弹窗 -->
        <div id="overlay">
            <div class="act-banner">
                <div class="act-title-small">第 1 幕</div>
                <div class="act-title-main">EXORDIUM · 外域</div>
            </div>
        </div>

    </div>

    <script>
        // 配置与数据
        const CONFIG = {
            nodeRadius: 12,
            colors: {
                path: '#8b7355',
                pathAvailable: '#d4a373',
                pathTaken: '#5c4033',
                enemy: '#a33b3b',
                elite: '#b7791f',
                boss: '#c53030',
                treasure: '#2f855a',
                rest: '#3182ce'
            }
        };

        // 简单的地图生成算法 (基于网格的分叉)
        // 为了还原截图中的视觉风格：稀疏、有曲线感
        const mapData = generateMapData();

        function generateMapData() {
            const nodes = [];
            const edges = [];

            // 定义列
            const cols = 10; 
            const rows = 7;
            const startX = 100;
            const spacingX = 65;
            const centerY = 300;

            // 第一列：起始点
            nodes.push({ id: 0, x: startX, y: centerY, type: 'start' });

            let currentIds = [0];

            for (let c = 1; c <= cols; c++) {
                const nextIds = [];
                const colX = startX + c * spacingX;

                // 根据列数决定这一列有几个节点（模拟截图中的疏密）
                // 截图中看起来是分叉结构
                let countInCol = 1;
                if (c > 1 && c < cols-1) {
                    countInCol = Math.random() > 0.3 ? 2 : 1;
                    if (c > 3) countInCol = Math.random() > 0.5 ? 3 : 2;
                }

                // 限制最大数量防止太乱
                if (currentIds.length === 1 && c < 3) countInCol = 2;

                // 生成该列节点的Y坐标
                // 使用正弦波或随机偏移来制造“波浪”感
                let yOffsets = [];
                if (countInCol === 1) {
                    yOffsets = [centerY + (Math.random() - 0.5) * 50];
                } else if (countInCol === 2) {
                    yOffsets = [centerY - 40 - Math.random()*30, centerY + 40 + Math.random()*30];
                } else {
                    yOffsets = [centerY - 80, centerY, centerY + 80];
                }

                yOffsets.forEach((offset, idx) => {
                    const newNodeId = nodes.length;
                    // 稍微加点随机扰动让线不直
                    const jitterX = (Math.random() - 0.5) * 20; 
                    const finalY = offset + (Math.random() - 0.5) * 20;

                    // 决定类型
                    let type = 'enemy';
                    if (c === cols) type = 'boss';
                    else if (c === cols - 1) type = 'treasure';
                    else if (c % 3 === 0) type = Math.random() > 0.5 ? 'elite' : 'rest';
                    else if (Math.random() > 0.8) type = 'event';

                    nodes.push({ 
                        id: newNodeId, 
                        x: colX + jitterX, 
                        y: finalY, 
                        type: type,
                        available: (c === 1) // 只有第一层的点是可用的
                    });
                    nextIds.push(newNodeId);

                    // 连接边：从上一层的某个点连接过来
                    // 简单逻辑：轮流连接或者随机连接
                    const parentIdx = idx % currentIds.length;
                    const parentId = currentIds[parentIdx];

                    // 如果是第二层以上的点，可能需要更复杂的连线逻辑来形成网状
                    // 这里简化为树状+少量交叉
                    edges.push({ from: parentId, to: newNodeId });
                });

                currentIds = nextIds;
            }

            return { nodes, edges };
        }

        // 渲染函数
        function renderMap() {
            const pathsLayer = document.getElementById('paths-layer');
            const nodesLayer = document.getElementById('nodes-layer');

            // 1. 绘制路径 (使用贝塞尔曲线让路看起来自然)
            mapData.edges.forEach(edge => {
                const startNode = mapData.nodes.find(n => n.id === edge.from);
                const endNode = mapData.nodes.find(n => n.id === edge.to);

                if (!startNode || !endNode) return;

                // 判断路径状态
                // 假设第一段是 taken (演示用)，或者全部 available
                // 这里为了视觉效果，我们根据节点是否 available 来决定路径颜色，
                // 或者简单点：所有路径都是虚线，除了起始路径。
                let pathClass = 'map-path';
                let pathColor = CONFIG.colors.path;

                // 如果是第一层连接，设为高亮可用
                if (endNode.available || startNode.type === 'start') {
                    pathClass += ' available';
                    pathColor = CONFIG.colors.pathAvailable;
                }

                // 创建曲线路径
                // 控制点计算：中点 + 随机偏移
                const midX = (startNode.x + endNode.x) / 2;
                const midY = (startNode.y + endNode.y) / 2;
                // 让控制点稍微偏离直线，产生弧度
                const cpOffset = (startNode.y - endNode.y) * 0.2; 

                const pathEl = document.createElementNS("http://www.w3.org/2000/svg", "path");
                // M start Q control end
                const d = `M ${startNode.x} ${startNode.y} Q ${midX} ${midY + cpOffset} ${endNode.x} ${endNode.y}`;

                pathEl.setAttribute("d", d);
                pathEl.setAttribute("class", pathClass);
                pathEl.setAttribute("stroke", pathColor);
                // 填充none
                pathEl.setAttribute("fill", "none");

                pathsLayer.appendChild(pathEl);
            });

            // 2. 绘制节点
            mapData.nodes.forEach(node => {
                const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
                g.setAttribute("transform", `translate(${node.x}, ${node.y})`);
                g.style.cursor = "pointer";

                // 外圈光晕 (如果是Boss或当前可选)
                if (node.type === 'boss' || node.available) {
                    const glow = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                    glow.setAttribute("r", CONFIG.nodeRadius + 5);
                    glow.setAttribute("fill", "rgba(255,255,255,0.2)");
                    g.appendChild(glow);
                }

                // 节点圆圈
                const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                circle.setAttribute("r", CONFIG.nodeRadius);
                circle.setAttribute("class", `node-circle node-${node.type}`);

                // 图标文字
                const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
                text.setAttribute("class", "node-icon");
                text.setAttribute("dy", "1"); // 微调垂直居中

                // 根据类型设置图标
                let icon = "?";
                switch(node.type) {
                    case 'enemy': icon = "⚔"; break;
                    case 'elite': icon = "💀"; break;
                    case 'boss': icon = "👹"; break;
                    case 'treasure': icon = "★"; break;
                    case 'rest': icon = "Zz"; break; // 或者用图标
                    case 'event': icon = "?"; break;
                    case 'shop': icon = "$"; break;
                    case 'start': icon = ""; break; // 起始点通常没图标或者是个箭头
                }
                text.textContent = icon;

                g.appendChild(circle);
                if(icon) g.appendChild(text);

                // 点击事件
                g.addEventListener('click', () => {
                    alert(`进入节点: ${node.type.toUpperCase()} (ID: ${node.id})`);
                });

                nodesLayer.appendChild(g);
            });
        }

        // 初始化
        window.onload = () => {
            renderMap();

            // 模拟点击遮罩消失
            setTimeout(() => {
                const overlay = document.getElementById('overlay');
                overlay.style.transition = "opacity 1s";
                overlay.style.opacity = 0;
                setTimeout(() => overlay.style.display = "none", 1000);
            }, 2500); // 2.5秒后淡出
        };

    </script>
</body>
</html>
